mapper.select:
SELECT COUNT(DISTINCT a.id)
FROM t_article a
LEFT JOIN t_article_tag tat ON a.id = tat.article_id

    is_delete = #{condition.isDelete}

        and article_title like concat('%',#{condition.keyword},'%')


        and `status` = #{condition.status}


        and article_type = #{condition.articleType}


        and category_id = #{condition.categoryId}


        and tat.tag_id = #{condition.tagId}

SELECT a.id, article_cover, article_title, article_type, category_name, is_top, is_recommend, a.is_delete, a.`status`, a.create_time, t.id AS tag_id, t.tag_name FROM ( SELECT id, article_cover, category_id, article_title, article_type, is_top, is_recommend, is_delete, `status`, create_time FROM t_article
is_delete = #{condition.isDelete}
and article_title like concat('%',#{condition.keyword},'%')
and status = #{condition.status}
and category_id = #{condition.categoryId}
and article_type = #{condition.articleType}
and id in ( SELECT article_id FROM t_article_tag WHERE tag_id = #{condition.tagId} )
ORDER BY is_top DESC, is_recommend DESC, id DESC LIMIT #{limit}, #{size} ) a LEFT JOIN t_category c ON a.category_id = c.id LEFT JOIN t_article_tag tat ON a.id = tat.article_id LEFT JOIN t_tag t ON t.id = tat.tag_id

SELECT a.id, article_cover, article_title, SUBSTR(article_content, 1, 500) AS article_content, a.create_time, a.article_type, a.is_top, a.category_id, category_name, t.id AS tag_id, t.tag_name FROM (SELECT id, article_cover, article_title, SUBSTR(article_content, 1, 500) AS article_content, create_time, article_type, is_top, views, category_id FROM t_article WHERE is_delete = 0
AND create_time BETWEEN #{start} AND #{end}
AND `status` = 1 AND id IN ( SELECT tat.article_id FROM t_article_tag tat INNER JOIN t_tag t ON tat.tag_id = t.id ) ORDER BY is_top DESC, ${sort} DESC, id DESC ) a INNER JOIN t_category c ON a.category_id = c.id INNER JOIN t_article_tag tat ON a.id = tat.article_id INNER JOIN t_tag t ON t.id = tat.tag_id
WHERE t.id = #{tagId}
ORDER BY a.is_top DESC, a.${sort} DESC,a.id DESC

SELECT a.id, article_cover, article_title, SUBSTR(article_content, 1, 500) AS article_content, a.create_time, a.article_type, a.is_top, a.category_id, category_name, t.id AS tag_id, t.tag_name FROM (SELECT id, article_cover, article_title, SUBSTR(article_content, 1, 500) AS article_content, create_time, article_type, is_top, views, category_id FROM t_article WHERE is_delete = 0
AND create_time BETWEEN #{start} AND #{end}
AND `status` = 1 AND id IN ( SELECT tat.article_id FROM t_article_tag tat INNER JOIN t_tag t ON tat.tag_id = t.id )
ORDER BY is_top DESC, ${sort} DESC, id DESC ) a INNER JOIN t_category c ON a.category_id = c.id INNER JOIN t_article_tag tat ON a.id = tat.article_id INNER JOIN t_tag t ON t.id = tat.tag_id
WHERE t.id = #{tagId}
ORDER BY a.is_top DESC, a.${sort} DESC,a.id DESC

SELECT a.content_version, a.views, a.category_id, c.category_name, t.id AS tag_id, t.tag_name, p.id AS last_id, p.article_cover AS last_cover, p.article_title AS last_title, n.id AS next_id, n.article_cover AS next_cover, n.article_title AS next_title FROM t_article a INNER JOIN t_category c ON a.category_id = c.id INNER JOIN t_article_tag tat ON a.id = tat.article_id INNER JOIN t_tag t ON tat.tag_id = t.id LEFT JOIN t_article p ON p.id = ( SELECT MAX(prev_candidate.id) FROM t_article prev_candidate WHERE prev_candidate.id < #{articleId} AND prev_candidate.is_delete = 0 AND prev_candidate.`status` = 1
) LEFT JOIN t_article n ON n.id = ( SELECT MIN(next_candidate.id) FROM t_article next_candidate WHERE next_candidate.id > #{articleId} AND next_candidate.is_delete = 0 AND next_candidate.`status` = 1
) WHERE a.id = #{articleId} AND a.is_delete = 0 AND a.`status` = 1
